{
  "title": "Services and Data Processing Agreement",
  "planted": [
    {
      "slot": "p1",
      "text": "In the event of any security incident or unauthorized access involving personal data, the Vendor reserves the right to determine at its sole discretion whether to notify the Customer, and any such notification may be provided within a reasonable timeframe not to exceed thirty business days, without any strict obligation to provide prompt interim updates."
    },
    {
      "slot": "p2",
      "text": "The Vendor may process personal data strictly for the performance of the operational tasks for which it was originally collected, provided that aggregated datasets from which all individual identifiers have been permanently removed may be utilized for broader internal operational analysis."
    },
    {
      "slot": "p3",
      "text": "The Customer shall engage subcontractors to assist with data handling operations based on their general market reputation and standard industry certifications, subject to periodic reviews conducted at mutually agreed intervals."
    }
  ],
  "neutral": [
    "The term of this Agreement shall commence on the effective date and shall continue for an initial period of twelve months, automatically renewing for successive one-year terms unless either party provides written notice of non-renewal at least thirty days prior to the expiration of the current term.",
    "All fees for the services rendered shall be invoiced on a monthly basis in accordance with the pricing schedule set forth in the statement of work, and the Customer shall remit payment in full within thirty days following the receipt of each applicable invoice.",
    "Each party shall retain exclusive ownership of all intellectual property rights, software, trademarks, and proprietary methodologies developed independently prior to or outside the scope of this Agreement.",
    "This Agreement shall be governed by and construed in accordance with the laws applicable in the Kingdom of Saudi Arabia, without regard to its conflict of laws principles.",
    "Neither party shall be held liable to the other for any indirect, incidental, consequential, or special damages arising out of or in connection with the performance of services under this Agreement, regardless of the theory of liability."
  ]
}
